 13	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 14	public final class ReservationService {
 15	
 16	    static final String HOTEL_NAME = "Pousada Maré Alta";
 17	
 18	    private final Rooms rooms;
 19	    private final ReservationStore store;
 20	    private final PriceCalculator priceCalculator;
 21	    private static final Logger LOG = LoggerFactory.getLogger(ReservationService.class);
 22	
 23	    private final EmailSender emailSender;
 24	    private final List<ReservationListener> listeners;
 25	
 26	    public ReservationService(
 27	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 28	        this(rooms, store, priceCalculator, emailSender, List.of());
 29	    }
 30	
 31	    public ReservationService(
 32	            Rooms rooms,
 33	            ReservationStore store,
 34	            PriceCalculator priceCalculator,
 35	            EmailSender emailSender,
 36	            List<ReservationListener> listeners) {
 37	        this.listeners = List.copyOf(listeners);
 38	        this.rooms = rooms;
 39	        this.store = store;
 40	        this.priceCalculator = priceCalculator;
 41	        this.emailSender = emailSender;
 42	    }
 43	
 44	    public synchronized Reservation create(NewReservation request) {
 45	        if (!request.checkOut().isAfter(request.checkIn())) {
 46	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 47	        }
 48	        if (request.guests() < 1) {
 49	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 50	        }
 51	        Room room = rooms.find(request.roomNumber())
 52	                .orElseThrow(() -> new HotelException(
 53	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 54	        if (request.guests() > room.capacity()) {
 55	            throw new HotelException(
 56	                    ErrorCode.CAPACITY_EXCEEDED,
 57	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 58	        }
 59	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 60	            throw new HotelException(
 61	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 62	        }
 63	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 64	        return store.add(request, price);
 65	    }
 66	
 67	    public Reservation find(long reservationId) {
 68	        return store.find(reservationId)
 69	                .orElseThrow(() -> new HotelException(
 70	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 71	    }
 72	
 73	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 74	    public synchronized Reservation confirm(long reservationId) {
 75	        Reservation reservation = find(reservationId);
 76	        if (reservation.status() != ReservationStatus.PENDING) {
 77	            throw notAllowed(reservation, "confirm");
 78	        }
 79	        reservation.confirmPayment();
 80	        store.update(reservation);
 81	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 82	        emailSender.send(
 83	                reservation.guest().email(),
 84	                "Reserva confirmada - " + HOTEL_NAME,
 85	                confirmationEmailBody(reservation, receipt));
 86	        notifyListeners(listener -> listener.confirmed(reservation, roomOf(reservation)));
 87	        return reservation;
 88	    }
 89	
 90	    /**
 91	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 92	     * reservation was never paid, so nothing comes back).
 93	     */
 94	    public synchronized Reservation cancel(long reservationId) {
 95	        Reservation reservation = find(reservationId);
 96	        if (reservation.status() != ReservationStatus.PENDING
 97	                && reservation.status() != ReservationStatus.CONFIRMED) {
 98	            throw notAllowed(reservation, "cancel");
 99	        }
100	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
101	        BigDecimal refund = switch (reservation.ratePlan()) {
102	            case STANDARD -> reservation.amountPaid();
103	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
104	        };
105	        reservation.cancel(refund);
106	        store.update(reservation);
107	        if (wasConfirmed) {
108	            notifyListeners(listener -> listener.confirmedReservationCancelled(reservation, roomOf(reservation)));
109	        }
110	        return reservation;
111	    }
112	
113	    /** A failing listener must not undo the reservation change, nor keep the others from hearing of it. */
114	    private void notifyListeners(Consumer<ReservationListener> event) {
115	        for (ReservationListener listener : listeners) {
116	            try {
117	                event.accept(listener);
118	            } catch (RuntimeException failure) {
119	                LOG.error("reservation listener {} failed", listener.getClass().getName(), failure);
120	            }
121	        }
122	    }
123	
124	    public synchronized Reservation checkIn(long reservationId) {
125	        Reservation reservation = find(reservationId);
126	        if (reservation.status() != ReservationStatus.CONFIRMED) {
127	            throw notAllowed(reservation, "check in");
128	        }
129	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
130	        store.update(reservation);
131	        return reservation;
132	    }
133	
134	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
135	    public synchronized ReservationReceipt checkOut(long reservationId) {
136	        Reservation reservation = find(reservationId);
137	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
138	            throw notAllowed(reservation, "check out");
139	        }
140	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
141	        store.update(reservation);
142	        return new ReservationReceipt(reservation, roomOf(reservation));
143	    }
144	
145	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
146	    public ReservationReceipt receiptCopy(long reservationId) {
147	        Reservation reservation = find(reservationId);
148	        if (!reservation.isPaid()) {
149	            throw notAllowed(reservation, "issue a receipt for");
150	        }
151	        return new ReservationReceipt(reservation, roomOf(reservation));
152	    }
153	
154	    private Room roomOf(Reservation reservation) {
155	        return rooms.find(reservation.roomNumber()).orElseThrow();
156	    }
157	
158	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
159	        return "Olá, " + reservation.guest().name() + "!\n\n"
160	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
161	                + receipt.text() + "\n"
162	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
163	                + "Até breve!\n";
164	    }
165	
166	    private static HotelException notAllowed(Reservation reservation, String operation) {
167	        return new HotelException(
168	                ErrorCode.OPERATION_NOT_ALLOWED,
169	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
170	    }
171	}
